import json
import os
from datetime import datetime, timedelta, timezone

import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
INDUSTRY_ID = os.getenv("INDUSTRY_ID", "industrial-facility")
USAGE_DETAILS = os.getenv("USAGE_DETAILS")
MAINTENANCE_DAYS_AHEAD = int(os.getenv("MAINTENANCE_DAYS_AHEAD", "30"))

session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def request_json(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.status_code == 204 or not response.content:
        return None
    return response.json()


def records_from(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("equipment", "items", "data", "results", "schedule", "activities"):
            value = data.get(key)
            if isinstance(value, list):
                return value
    return []


def first_value(record, *keys):
    for key in keys:
        value = record.get(key)
        if value is not None:
            return value
    return None


results = {
    "maintenance_schedule": None,
    "equipment_status": None,
    "efficiency_evaluations": [],
    "maintenance_plans": [],
    "maintenance_report_feedback": [],
}

try:
    results["maintenance_schedule"] = request_json("GET", "/maintenance-schedule")
    results["equipment_status"] = request_json("GET", "/equipment-status")

    equipment = records_from(results["equipment_status"])
    schedule = records_from(results["maintenance_schedule"])

    for item in equipment:
        equipment_id = first_value(
            item, "equipmentId", "equipment_id", "resource_id", "resourceId", "id"
        )
        if not equipment_id:
            continue

        usage_details = USAGE_DETAILS or json.dumps(item, default=str)
        evaluation = request_json(
            "POST",
            "/equipment-efficiency-check",
            json={
                "equipmentId": str(equipment_id),
                "industryId": INDUSTRY_ID,
                "usageDetails": usage_details,
            },
        )
        results["efficiency_evaluations"].append(
            {"equipmentId": str(equipment_id), "evaluation": evaluation}
        )

        maintenance_date = (
            datetime.now(timezone.utc) + timedelta(days=MAINTENANCE_DAYS_AHEAD)
        ).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        plan = request_json(
            "PUT",
            "/resources/maintenance",
            json={
                "resource_id": str(equipment_id),
                "maintenance_date": maintenance_date,
                "notes": (
                    "Planned routine maintenance. Review current equipment status "
                    "and efficiency evaluation before confirming work."
                ),
            },
        )
        results["maintenance_plans"].append(
            {"resource_id": str(equipment_id), "plan": plan}
        )

    scheduled_ids = {
        str(first_value(entry, "equipmentId", "equipment_id", "resource_id", "resourceId", "id"))
        for entry in schedule
        if first_value(entry, "equipmentId", "equipment_id", "resource_id", "resourceId", "id")
        is not None
    }
    for item in equipment:
        equipment_id = first_value(
            item, "equipmentId", "equipment_id", "resource_id", "resourceId", "id"
        )
        if equipment_id is not None and str(equipment_id) not in scheduled_ids:
            results["maintenance_report_feedback"].append(
                f"Equipment {equipment_id} appears in current status data but could not "
                "be matched to an entry in the maintenance schedule; add or verify its "
                "planned maintenance activity."
            )

    for entry in schedule:
        status = str(first_value(entry, "status") or "").lower()
        if status in {"overdue", "missed", "delayed"}:
            results["maintenance_report_feedback"].append(
                f"Schedule entry {first_value(entry, 'id', 'scheduleId') or '(unknown ID)'} "
                f"is marked {status}; verify its date and reschedule if necessary."
            )

    if not results["maintenance_report_feedback"]:
        results["maintenance_report_feedback"].append(
            "No obvious mismatch or overdue status was found from the available "
            "schedule and equipment status data. Confirm dates, equipment identifiers, "
            "and completion statuses against facility maintenance records."
        )

except requests.RequestException as exc:
    results["error"] = str(exc)

print(json.dumps(results, indent=2, default=str))

