import json
import os
from datetime import date, timedelta

import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json"})

results = {}


def get_json(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    return response.json()


def post_json(path, payload):
    response = session.post(
        f"{BASE_URL}{path}",
        json=payload,
        timeout=30,
    )
    response.raise_for_status()
    return response.json()


def numeric_demand_values(data):
    values = []

    def visit(obj, key_hint=""):
        if isinstance(obj, dict):
            for key, value in obj.items():
                visit(value, str(key).lower())
        elif isinstance(obj, list):
            for item in obj:
                visit(item, key_hint)
        elif (
            isinstance(obj, (int, float))
            and not isinstance(obj, bool)
            and any(term in key_hint for term in ("demand", "usage", "consumption", "load"))
        ):
            values.append(float(obj))

    visit(data)
    return values


end_date = date.today()
start_date = end_date - timedelta(days=30)

results["historical_demand"] = get_json(
    "/electricity-demand",
    params={
        "start_date": start_date.isoformat(),
        "end_date": end_date.isoformat(),
    },
)

# Review monitored resource status as operational context; no maintenance-schedule
# retrieval endpoint is documented.
results["resource_status"] = get_json("/resources/status")

results["real_time_data"] = get_json("/real-time-data")
results["grid_balance"] = get_json("/grid/balance/status")
results["wind_generation"] = get_json("/generation/wind")

usage_patterns = numeric_demand_values(results["historical_demand"])
results["optimization"] = post_json(
    "/optimize-usage",
    {
        "usagePatterns": usage_patterns,
        "parameters": {
            "analysis": "historical electricity demand trend identification",
            "start_date": start_date.isoformat(),
            "end_date": end_date.isoformat(),
        },
    },
)

# Supply actual integration details as JSON in RENEWABLE_INTEGRATION, for example:
# {"source":"solar","capacity":12.5,"integration_status":"integrated"}
integration_config = os.getenv("RENEWABLE_INTEGRATION")
if integration_config:
    integration_payload = json.loads(integration_config)
    results["renewable_integration"] = post_json(
        "/renewable/integration/status",
        integration_payload,
    )

# The documented API has no endpoint for writing real-time data to an energy
# usage database, retrieving cost breakdowns, or configuring alerts. The
# maintenance endpoint schedules a specific resource but does not retrieve a
# maintenance schedule, so it is not called here.

