import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30


def response_data(response):
    response.raise_for_status()
    try:
        return response.json()
    except ValueError:
        return response.text


def analyze_materials_and_equipment(material_ids, equipment_id, aligned_updates=None):
    """
    aligned_updates maps material IDs to MaterialInput payloads prepared to meet
    the applicable requirements. The API documentation does not define how to
    derive those payloads from compliance results.
    """
    aligned_updates = aligned_updates or {}
    results = {
        "standards": None,
        "materials": {},
        "equipment_analysis": None,
        "equipment_metrics": None,
        "unsupported": {
            "notifications": "No notification endpoint is documented.",
            "site_resources": "No endpoint for site-specific resource types is documented.",
        },
    }

    results["standards"] = response_data(
        requests.get(f"{BASE_URL}/standards", timeout=TIMEOUT)
    )

    for material_id in material_ids:
        material = response_data(
            requests.get(f"{BASE_URL}/materials/{material_id}", timeout=TIMEOUT)
        )
        compliance = response_data(
            requests.get(
                f"{BASE_URL}/materials/{material_id}/compliance",
                timeout=TIMEOUT,
            )
        )

        material_result = {
            "details": material,
            "compliance": compliance,
            "update": None,
        }

        if material_id in aligned_updates:
            material_result["update"] = response_data(
                requests.put(
                    f"{BASE_URL}/materials/{material_id}",
                    json=aligned_updates[material_id],
                    timeout=TIMEOUT,
                )
            )

        results["materials"][material_id] = material_result

    results["equipment_analysis"] = response_data(
        requests.post(
            f"{BASE_URL}/analysis/start",
            json={"equipmentId": equipment_id},
            timeout=TIMEOUT,
        )
    )

    results["equipment_metrics"] = response_data(
        requests.get(
            f"{BASE_URL}/equipment/{equipment_id}/metrics",
            timeout=TIMEOUT,
        )
    )

    return results


if __name__ == "__main__":
    MATERIAL_IDS = []  # Supply the material IDs to assess.
    EQUIPMENT_ID = ""  # Supply the machinery ID.
    ALIGNED_UPDATES = {}  # Optional: material ID -> MaterialInput payload.

    report = analyze_materials_and_equipment(
        MATERIAL_IDS,
        EQUIPMENT_ID,
        aligned_updates=ALIGNED_UPDATES,
    )
    print(report)

