import json
import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})

results = {
    "categories": None,
    "classifications": [],
    "compliance_checks": [],
    "inventory_status": None,
    "classification_statistics": None,
}

def get_json(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", **kwargs)
    response.raise_for_status()
    return response.json()

def post_json(path, payload):
    response = session.post(f"{BASE_URL}{path}", json=payload)
    response.raise_for_status()
    return response.json()

try:
    results["categories"] = get_json("/materials/categories")
except requests.RequestException as exc:
    results["categories_error"] = str(exc)

categories = results["categories"]
if isinstance(categories, dict):
    categories = (
        categories.get("categories")
        or categories.get("materials")
        or categories.get("data")
        or []
    )
if not isinstance(categories, list):
    categories = []

for item in categories:
    if isinstance(item, str):
        material_name = item
        properties = {}
    elif isinstance(item, dict):
        material_name = (
            item.get("materialName")
            or item.get("name")
            or item.get("category")
        )
        properties = item.get("properties") or {}
        if not isinstance(properties, dict):
            properties = {}
        properties = {str(key): str(value) for key, value in properties.items()}
    else:
        continue

    if not material_name:
        continue

    record = {"materialName": material_name, "properties": properties}
    try:
        classification = post_json("/materials/classify", record)
        entry = {"materialName": material_name, "classification": classification}
        results["classifications"].append(entry)

        # Check compliance when classification identifies a material ID.
        classification_data = classification
        if isinstance(classification_data, dict) and isinstance(
            classification_data.get("data"), dict
        ):
            classification_data = classification_data["data"]

        material_id = None
        if isinstance(classification_data, dict):
            material_id = (
                classification_data.get("materialId")
                or classification_data.get("id")
            )

        if material_id:
            try:
                compliance = get_json(
                    f"/materials/{requests.utils.quote(str(material_id), safe='')}/compliance"
                )
                results["compliance_checks"].append(
                    {"materialId": material_id, "result": compliance}
                )
            except requests.RequestException as exc:
                results["compliance_checks"].append(
                    {"materialId": material_id, "error": str(exc)}
                )
    except requests.RequestException as exc:
        results["classifications"].append(
            {"materialName": material_name, "error": str(exc)}
        )

try:
    results["inventory_status"] = get_json("/inventory/status")
except requests.RequestException as exc:
    results["inventory_status_error"] = str(exc)

try:
    # The documented statistics endpoint reports material classification statistics,
    # not resource-usage statistics.
    results["classification_statistics"] = get_json("/analysis/statistics")
except requests.RequestException as exc:
    results["classification_statistics_error"] = str(exc)

# The documentation provides no endpoint for updating shipment routes,
# scheduling machinery maintenance, or retrieving resource-usage statistics.
results["unsupported_operations"] = [
    "Shipment route updates",
    "Machinery maintenance scheduling",
    "Resource-usage statistics",
]

