import json
import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()


def get_json(response):
    response.raise_for_status()
    if not response.content:
        return None
    return response.json()


def records(data, collection_key):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        value = data.get(collection_key)
        if isinstance(value, list):
            return value
    return []


def find_id(data, keys):
    if isinstance(data, dict):
        for key in keys:
            if data.get(key) is not None:
                return str(data[key])
        for value in data.values():
            if isinstance(value, dict):
                found = find_id(value, keys)
                if found:
                    return found
    return None


# Use available inventory items to create two orders.
inventory_data = get_json(session.get(f"{BASE_URL}/items", timeout=30))
inventory = records(inventory_data, "items")
if not inventory:
    raise RuntimeError("Cannot create orders or select an item to remove: inventory is empty.")

item_ids = [
    str(item.get("item_id", item.get("id")))
    for item in inventory
    if isinstance(item, dict) and item.get("item_id", item.get("id")) is not None
]
if not item_ids:
    raise RuntimeError("Inventory records do not contain item IDs.")

created_order_ids = []
for index in range(2):
    item_id = item_ids[index % len(item_ids)]
    response = session.post(
        f"{BASE_URL}/orders",
        json={"items": [{"item_id": item_id, "quantity": 1}]},
        timeout=30,
    )
    created_data = get_json(response)
    order_id = find_id(created_data, ("order_id", "id"))
    if order_id:
        created_order_ids.append(order_id)

# Retrieve all orders and fetch details for one specific order.
orders_data = get_json(session.get(f"{BASE_URL}/orders", timeout=30))
orders = records(orders_data, "orders")
print("Orders summary:")
print(json.dumps(orders_data, indent=2))

detail_order_id = created_order_ids[0] if created_order_ids else None
if detail_order_id is None and orders:
    detail_order_id = find_id(orders[0], ("order_id", "id"))

if detail_order_id:
    order_detail = get_json(
        session.get(f"{BASE_URL}/orders/{detail_order_id}", timeout=30)
    )
    print(f"Details for order {detail_order_id}:")
    print(json.dumps(order_detail, indent=2))
else:
    print("No order ID was available to retrieve order details.")

# Review upcoming maintenance schedules and create a local resource-planning view.
maintenance_data = get_json(
    session.get(f"{BASE_URL}/maintenance_schedule", timeout=30)
)
schedules = records(maintenance_data, "schedules")
if not schedules and isinstance(maintenance_data, dict):
    schedules = records(maintenance_data, "maintenance_schedule")

def schedule_priority(schedule):
    if not isinstance(schedule, dict):
        return (3, "")
    urgency = str(
        schedule.get("priority", schedule.get("severity", schedule.get("urgency", "")))
    ).lower()
    rank = 0 if urgency in ("critical", "urgent", "high") else (
        1 if urgency in ("medium", "moderate") else (
            2 if urgency in ("low", "normal") else 3
        )
    )
    date = str(
        schedule.get("date", schedule.get("scheduled_date", schedule.get("due_date", "")))
    )
    return rank, date


prioritized_schedules = sorted(schedules, key=schedule_priority)
resource_plan = [
    {
        "schedule": schedule,
        "suggested_resource_allocation": "Assign maintenance resources according to priority and scheduled date.",
    }
    for schedule in prioritized_schedules
]
print("Maintenance schedules and suggested resource plan:")
print(json.dumps(resource_plan, indent=2))

# Remove the first inventory item to optimize operations.
item_to_remove = inventory[0]
item_to_remove_id = item_to_remove.get("item_id", item_to_remove.get("id"))
if item_to_remove_id is None:
    raise RuntimeError("The selected inventory record does not contain an item ID.")

delete_response = session.delete(
    f"{BASE_URL}/items/{item_to_remove_id}",
    timeout=30,
)
delete_response.raise_for_status()
print(f"Removed inventory item {item_to_remove_id}.")

