import json
import re
import requests

BASE_URL = "https://api.socbench.example"

allergens_response = requests.get(f"{BASE_URL}/allergens", timeout=30)
allergens_response.raise_for_status()
allergens_data = allergens_response.json()

overview_response = requests.get(f"{BASE_URL}/supplychain/overview", timeout=30)
overview_response.raise_for_status()
overview_data = overview_response.json()

overview_text = json.dumps(overview_data, ensure_ascii=False).casefold()


def string_values(value, path="$"):
    if isinstance(value, dict):
        for key, item in value.items():
            yield from string_values(item, f"{path}.{key}")
    elif isinstance(value, list):
        for index, item in enumerate(value):
            yield from string_values(item, f"{path}[{index}]")
    elif isinstance(value, str):
        yield path, value


matches = []
seen = set()

for path, term in string_values(allergens_data):
    term = term.strip()
    if len(term) < 3:
        continue

    pattern = r"(?<!\w)" + re.escape(term.casefold()) + r"(?!\w)"
    if re.search(pattern, overview_text):
        key = term.casefold()
        if key not in seen:
            matches.append({"possibleAllergenOrFood": term, "source": path})
            seen.add(key)

print(json.dumps({
    "possibleAllergenMatches": matches,
    "matchCount": len(matches)
}, ensure_ascii=False, indent=2))

