def find_segment_ids(data):
    """Extract segment identifiers from segment collections in the overview."""
    found = set()

    def walk(value):
        if isinstance(value, dict):
            for key, child in value.items():
                if key.lower() in {"segments", "supplychainsegments", "supply_chain_segments"}:
                    inspect_segments(child)
                walk(child)
        elif isinstance(value, list):
