        elif isinstance(value, dict):
            segment_id = value.get("segmentId") or value.get("id")
            if segment_id is not None:
                found.add(str(segment_id))
            for child in value.values():
                if isinstance(child, (dict, list)):
                    inspect_segments(child)

    walk(data)
    return sorted(found)


