import json
import requests
from datetime import date

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def get_json(path, params=None):
    response = session.get(f"{BASE_URL}{path}", params=params, timeout=30)
    response.raise_for_status()
    return response.json()


def post_json(path, payload):
    response = session.post(f"{BASE_URL}{path}", json=payload, timeout=30)
    response.raise_for_status()
    return response.json()


def collect_records(value):
    if isinstance(value, dict):
        yield value
        for child in value.values():
            yield from collect_records(child)
    elif isinstance(value, list):
        for child in value:
            yield from collect_records(child)


def numeric_field(record, fields):
    for field in fields:
        value = record.get(field)
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return value
    return None


inventory_data = get_json("/inventory/status")
patterns_data = get_json("/analytics/patterns")

historical_data = []
for record in collect_records(patterns_data):
    item_id = record.get("itemId")
    record_date = record.get("date")
    quantity_sold = record.get("quantitySold")
    if (
        isinstance(item_id, str)
        and isinstance(record_date, str)
        and isinstance(quantity_sold, int)
        and not isinstance(quantity_sold, bool)
    ):
        historical_data.append(
            {"date": record_date, "quantitySold": quantity_sold, "itemId": item_id}
        )

forecast_data = post_json(
    "/analytics/forecast",
    {"historicalData": historical_data},
)

stock_by_item = {}
for record in collect_records(inventory_data):
    item_id = record.get("itemId", record.get("id"))
    quantity = numeric_field(
        record, ("quantity", "currentQuantity", "stock", "onHand", "availableQuantity")
    )
    if isinstance(item_id, str) and quantity is not None:
        stock_by_item[item_id] = stock_by_item.get(item_id, 0) + quantity

demand_by_item = {}
for record in collect_records(forecast_data):
    item_id = record.get("itemId", record.get("id"))
    demand = numeric_field(
        record,
        (
            "predictedDemand",
            "forecastedDemand",
            "predictedQuantity",
            "forecastQuantity",
            "quantityNeeded",
            "quantity",
        ),
    )
    if isinstance(item_id, str) and demand is not None:
        demand_by_item[item_id] = max(demand_by_item.get(item_id, 0), demand)

ordered_items = []
for item_id, demand in demand_by_item.items():
    required_quantity = max(0, int(demand - stock_by_item.get(item_id, 0)))
    if required_quantity:
        ordered_items.append({"itemId": item_id, "quantity": required_quantity})

order_result = None
if ordered_items:
    order_result = post_json("/orders/new", {"items": ordered_items})

suppliers_data = get_json("/suppliers/list")
performance_metrics = get_json("/performance/metrics")
supply_chain_overview = get_json("/supplychain/overview")
waste_reports = get_json("/waste/reports")

result = {
