        {
            "itemId": item_id,
            "currentStock": stock_by_item.get(item_id, 0),
            "predictedDemand": demand_by_item[item_id],
            "orderQuantity": max(
                0, int(demand_by_item[item_id] - stock_by_item.get(item_id, 0))
            ),
        }
