import re
import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30
session = requests.Session()

def get_json(path):
    response = session.get(f"{BASE_URL}{path}", timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()

def send_json(method, path, payload=None):
    response = session.request(
        method,
        f"{BASE_URL}{path}",
        json=payload,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    try:
        return response.json()
    except ValueError:
        return {"status_code": response.status_code, "text": response.text}

def normalize(key):
    return re.sub(r"[^a-z0-9]", "", str(key).lower())

def records_with_zone_id(data):
    records = []

    def walk(value):
        if isinstance(value, dict):
            normalized = {normalize(k): v for k, v in value.items()}
            zone_id = next(
                (
                    normalized[key]
                    for key in ("zoneid", "zone", "id")
                    if isinstance(normalized.get(key), (str, int))
                ),
                None,
            )
            if zone_id is not None:
                records.append((str(zone_id), value))
            for child in value.values():
                if isinstance(child, (dict, list)):
                    walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)

    walk(data)
    return records

def metric(record, aliases):
    if not isinstance(record, dict):
        return None
    normalized = {normalize(k): v for k, v in record.items()}
    for alias in aliases:
        value = normalized.get(normalize(alias))
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return float(value)
    for key, value in normalized.items():
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            if any(normalize(alias) in key for alias in aliases):
                return float(value)
    return None

def first_available(*values):
    return next((value for value in values if value is not None), None)

demand_data = get_json("/realtime-demand")
forecast_data = get_json("/forecast-patterns")
status_data = get_json("/zones-status")
renewables_data = get_json("/renewables-status")
efficiency_data = get_json("/efficiency-reports")

forecast_by_zone = {}
for zone_id, record in records_with_zone_id(forecast_data):
    forecast_by_zone[zone_id] = record

status_by_zone = {}
for zone_id, record in records_with_zone_id(status_data):
    status_by_zone[zone_id] = record

zones = {}
demand_aliases = (
    "current_demand", "real_time_demand", "realtime_demand",
    "demand_mw", "electricity_demand", "demand", "load_mw", "load",
    "consumption_mw", "consumption",
)
supply_aliases = (
    "available_supply", "available_supply_mw", "supply_mw",
    "current_supply", "supply", "allocated_power",
)
forecast_aliases = (
    "forecast_demand", "predicted_demand", "projected_demand",
    "forecast_mw", "forecast", "expected_demand", "demand_mw",
    "demand", "consumption",
)

for zone_id, record in records_with_zone_id(demand_data):
    forecast_record = forecast_by_zone.get(zone_id, {})
    status_record = status_by_zone.get(zone_id, {})
    current_demand = metric(record, demand_aliases)
    projected_demand = metric(forecast_record, forecast_aliases)
    supply = first_available(
        metric(record, supply_aliases),
        metric(status_record, supply_aliases),
    )
    zones[zone_id] = {
        "demand": current_demand,
        "forecast": projected_demand,
        "supply": supply,
        "record": record,
        "forecast_record": forecast_record,
    }

known_demands = [
    zone["demand"] for zone in zones.values()
    if zone["demand"] is not None
]
average_demand = (
    sum(known_demands) / len(known_demands) if known_demands else None
)

high_demand_zones = [
    zone_id for zone_id, zone in zones.items()
    if zone["demand"] is not None
    and (average_demand is None or zone["demand"] >= average_demand)
]

surges = []
if average_demand is not None:
    surges = [
        zone_id for zone_id, zone in zones.items()
        if zone["demand"] is not None
        and zone["demand"] > average_demand * 1.2
    ]

allocation_results = {}
threshold_results = {}
suggestions = {}

for zone_id in high_demand_zones:
    zone = zones[zone_id]
    demand = zone["demand"]
    projected = zone["forecast"]
    supply = zone["supply"]

    allocation = max(demand - supply, 0.0) if supply is not None else demand
    if allocation > 0:
        allocation_results[zone_id] = send_json(
            "POST",
            "/allocate-resources",
            {
                "zone_id": zone_id,
                "allocated_power": allocation,
                "priority": "high",
            },
        )

    reference_demand = max(
        value for value in (demand, projected) if value is not None
    )
    threshold_results[zone_id] = send_json(
        "PATCH",
        "/update-thresholds",
        {
            "zone_id": zone_id,
            "new_threshold": round(reference_demand * 1.15, 2),
        },
    )

    zone_suggestions = [
        "Shift flexible or nonessential loads to off-peak periods to reduce pressure during high-demand intervals."
    ]
    if projected is not None and projected > demand:
        zone_suggestions.append(
            "Plan demand response and pre-cooling or pre-heating before the forecasted increase."
        )
    if supply is not None and demand > supply:
        zone_suggestions.append(
            "Prioritize essential loads and stagger discretionary consumption while demand exceeds available supply."
        )
    if renewables_data:
        zone_suggestions.append(
            "Where renewable output is available, schedule flexible loads to coincide with renewable generation."
        )
    if efficiency_data:
        zone_suggestions.append(
            "Review zone efficiency findings and prioritize operational or equipment improvements for this high-demand zone."
        )
    suggestions[zone_id] = zone_suggestions

trend_summary = {
    zone_id: {
        "real_time_demand_mw": zone["demand"],
        "forecast_demand_mw": zone["forecast"],
        "trend": (
            "increasing"
            if zone["demand"] is not None
            and zone["forecast"] is not None
            and zone["forecast"] > zone["demand"]
            else "decreasing_or_stable"
            if zone["demand"] is not None and zone["forecast"] is not None
            else "forecast unavailable"
        ),
    }
    for zone_id, zone in zones.items()
}

override_reset = send_json("DELETE", "/override-settings")

print({
    "high_demand_zones": high_demand_zones,
    "surge_zones": surges,
    "forecast_trends": trend_summary,
    "resource_allocations": allocation_results,
    "surge_alert_threshold_updates": threshold_results,
    "energy_saving_suggestions": suggestions,
    "manual_override_reset": override_reset,
})

import json
import requests

BASE_URL = "https://api.socbench.example"


def response_data(response):
    response.raise_for_status()
    try:
        return response.json()
    except ValueError:
        return {}


def get_records(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("properties", "results", "data", "items"):
            value = data.get(key)
            if isinstance(value, list):
                return value
    return []


def get_property_id(record):
    if not isinstance(record, dict):
        return None
    return record.get("property_id") or record.get("id")


def get_agent(record):
    if not isinstance(record, dict):
        return None
    agent = record.get("agent") or record.get("listing_agent")
    if isinstance(agent, dict):
        return agent
    if isinstance(agent, str):
        return {"name": agent}
    return None


def main():
    miami_response = requests.get(
        f"{BASE_URL}/properties",
        params={"location": "Miami"},
        timeout=30,
    )
    miami_data = response_data(miami_response)
    miami_properties = get_records(miami_data)

    property_ids = [
        property_id
        for property_id in (get_property_id(record) for record in miami_properties)
        if property_id
    ][:3]

    if len(property_ids) >= 2:
        comparison_response = requests.get(
            f"{BASE_URL}/properties/comparison",
            params={"property_ids": ",".join(map(str, property_ids))},
            timeout=30,
        )
        comparison = response_data(comparison_response)
        print("Property comparison:")
        print(json.dumps(comparison, indent=2))
    else:
        print("Property comparison: fewer than two Miami properties with IDs were returned.")

    luxury_response = requests.get(
        f"{BASE_URL}/properties",
        params={"location": "Miami", "property_type": "luxury"},
        timeout=30,
    )
    luxury_data = response_data(luxury_response)
    luxury_properties = get_records(luxury_data)

    identified_agents = {}
    candidate_agents = {}
    for property_record in luxury_properties:
        agent = get_agent(property_record)
        if not agent:
            continue
        agent_key = str(agent.get("id") or agent.get("agent_id") or agent.get("name") or agent)
        candidate_agents[agent_key] = agent
        specialization = str(
            agent.get("specialization")
            or agent.get("specialty")
            or agent.get("expertise")
            or ""
        ).lower()
        if "luxury" in specialization:
            identified_agents[agent_key] = agent

    print("Agents explicitly identified as specializing in luxury homes:")
    print(json.dumps(list(identified_agents.values()), indent=2))
    if not identified_agents:
        print(
            "No explicit luxury specialization was present in the returned agent data. "
            "Agents associated with Miami luxury listings:"
        )
        print(json.dumps(list(candidate_agents.values()), indent=2))

    listing = {
        "title": "Luxury Miami Residence",
        "description": "A newly listed luxury property in Miami.",
        "price": 1500000,
        "location": "Miami",
        "property_type": "house",
        "amenities": ["pool", "parking"],
    }
    create_response = requests.post(
        f"{BASE_URL}/properties",
        json=listing,
        timeout=30,
    )
    created_property = response_data(create_response)
    print("Created property:")
    print(json.dumps(created_property, indent=2))

    created_id = get_property_id(created_property)
    if created_id is None and isinstance(created_property, dict):
        nested = created_property.get("property")
        created_id = get_property_id(nested) if isinstance(nested, dict) else None

    if created_id is not None:
        updated_listing = {
            **listing,
            "description": "Updated description: luxury Miami residence with premium amenities.",
            "price": 1600000,
        }
        update_response = requests.put(
            f"{BASE_URL}/properties/{created_id}",
            json=updated_listing,
            timeout=30,
        )
        updated_property = response_data(update_response)
        print("Updated property:")
        print(json.dumps(updated_property, indent=2))
    else:
        print("The create response did not include a property ID; the listing could not be updated.")

    saved_search = {
        "location": "Miami",
        "property_type": "luxury",
    }
    save_response = requests.post(
        f"{BASE_URL}/search-saved",
        json=saved_search,
        timeout=30,
    )
    print("Saved search:")
    print(json.dumps(response_data(save_response), indent=2))

    all_properties_response = requests.get(
        f"{BASE_URL}/properties",
        params={"location": "Miami"},
        timeout=30,
    )
    all_properties = response_data(all_properties_response)
    print("Properties available in Miami:")
    print(json.dumps(all_properties, indent=2))


if __name__ == "__main__":
    main()

